    if not aid:
        print("aid 为空，无法获取评论")
        return None
    url = "https://api.bilibili.com/x/v2/reply"
    params = {
        "type": 1,  # 评论类型，1表示视频评论
        "oid": aid,
        "pn": page,
        "ps": page_size,
        "sort": 2,  # 排序方式，2表示按热度排序
    }
    data = safe_request_json(url, params=params)
