def check_login():
    """
    判断用户是否登录
    """
    cookies = request.cookies # 获取cookie
    cookie_name = app.config['AUTH_COOKIE_NAME'] # 获取cookie名
    auth_cookie = cookies[cookie_name] if cookie_name in cookies else None
    if auth_cookie is None:
        return False

    auth_info = auth_cookie.split("#") # 通过#分割cookie
    if len(auth_info) != 2:
        return False

    try:
        user_info = User.query.filter_by(id=auth_info[1]).first() # 通过 id 查询用户
    except Exception:
        return False

    if user_info is None:
        return False

    if auth_info[0] != UserService.geneAuthCode(user_info):
        return False

    return user_info

